/* ============================================================
   GRAVEWAKE — UI
   ============================================================ */
:root {
  --ink: #08070d;
  --ink-2: #0d0b16;
  --panel: rgba(16, 13, 26, 0.86);
  --panel-edge: rgba(190, 165, 255, 0.22);
  --text: #e9e2f4;
  --muted: #9d93b4;
  --dim: #6d6484;
  --violet: #a77bff;
  --violet-2: #6c46c9;
  --gold: #f2c96b;
  --gold-2: #a97a2c;
  --blood: #e8556d;
  --teal: #5ce1d0;
  --blue: #6fa8ff;
  --hp: linear-gradient(90deg, #9d1f3a, #e0455f 55%, #ff7d8d);
  --xp: linear-gradient(90deg, #3b2b8c, #7d5bff 55%, #b9a2ff);
  --serif: "Cinzel", "Palatino Linotype", "Book Antiqua", Georgia, "Times New Roman", serif;
  --sans: "Avenir Next", "Segoe UI", system-ui, -apple-system, sans-serif;
  --pixel: "Courier New", ui-monospace, monospace;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  background: #07060c; color: var(--text);
  font-family: var(--sans);
  overflow: hidden;
  overscroll-behavior: none;
  -webkit-user-select: none; user-select: none;
  -webkit-touch-callout: none;
  touch-action: none;
}
button { font-family: inherit; color: inherit; border: 0; background: none; cursor: pointer; touch-action: manipulation; }
button:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; background: #05040a; }

#game {
  position: absolute; inset: 0; width: 100%; height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  touch-action: none;
}

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse 78% 72% at 50% 48%, transparent 36%, rgba(3, 2, 8, 0.34) 74%, rgba(2, 1, 6, 0.78) 100%),
    linear-gradient(180deg, rgba(4, 2, 10, 0.42), transparent 18%, transparent 82%, rgba(4, 2, 10, 0.45));
  mix-blend-mode: multiply;
}
#scanlines {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0.055;
  background: repeating-linear-gradient(0deg, #fff 0px, #fff 1px, transparent 1px, transparent 3px);
  mix-blend-mode: overlay;
}

/* ============================== HUD ============================== */
#hud {
  position: absolute; inset: 0; z-index: 10;
  pointer-events: none;
  display: flex; flex-direction: column; justify-content: space-between;
  padding: calc(var(--safe-t) + 8px) calc(var(--safe-r) + 12px) calc(var(--safe-b) + 10px) calc(var(--safe-l) + 12px);
  font-family: var(--sans);
}
.hud-top { display: flex; flex-direction: column; gap: 6px; width: 100%; }

.xp-row { position: relative; width: 100%; height: 14px; display: flex; align-items: center; }
.xp-track {
  position: absolute; left: 0; right: 0; top: 1px; height: 8px;
  background: linear-gradient(180deg, rgba(8,6,16,.92), rgba(20,15,36,.85));
  border: 1px solid rgba(167,123,255,.34);
  border-radius: 3px; overflow: hidden;
  box-shadow: inset 0 1px 4px rgba(0,0,0,.8), 0 0 12px rgba(120,80,255,.16);
}
.xp-fill {
  height: 100%; width: 0%;
  background: var(--xp);
  box-shadow: 0 0 12px rgba(150,110,255,.75), inset 0 0 6px rgba(255,255,255,.35);
  transition: width .14s ease-out;
}
.xp-shine {
  position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.22), transparent);
  transform: translateX(-100%);
  animation: xpShine 4.5s ease-in-out infinite;
}
@keyframes xpShine { 0%, 60% { transform: translateX(-110%); } 85%, 100% { transform: translateX(110%); } }
.level-badge {
  position: absolute; right: 4px; top: -3px; height: 20px; min-width: 44px;
  display: flex; align-items: center; justify-content: center; gap: 3px;
  padding: 0 7px;
  background: linear-gradient(180deg, #2a2047, #120e22);
  border: 1px solid rgba(190,160,255,.5);
  border-radius: 4px;
  font-family: var(--pixel); font-weight: 700; font-size: 12px; color: #efe6ff;
  box-shadow: 0 2px 8px rgba(0,0,0,.6), 0 0 14px rgba(130,90,255,.25);
  z-index: 2;
}
.lv-label { font-size: 7px; letter-spacing: .06em; color: #a98cff; transform: translateY(1px); }
.top-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.hud-left { display: flex; flex-direction: column; gap: 1px; padding-left: 2px; }
.timer {
  font-family: var(--serif); font-weight: 700; font-size: 30px; line-height: 1;
  letter-spacing: .06em; color: #f5edff;
  text-shadow: 0 2px 0 #150f28, 0 0 18px rgba(150,110,255,.4);
  font-variant-numeric: tabular-nums;
}
.zone-name {
  font-size: 8px; letter-spacing: .28em; color: rgba(200,185,230,.72);
  text-shadow: 0 1px 2px #000;
}
.hud-right { display: flex; align-items: center; gap: 8px; pointer-events: auto; }
.kill-chip {
  display: flex; align-items: center; gap: 5px; height: 26px; padding: 0 9px;
  background: rgba(12,9,22,.74); border: 1px solid rgba(200,170,255,.18);
  border-radius: 4px; backdrop-filter: blur(4px);
  font-family: var(--pixel); font-size: 11px; font-weight: 700; color: #ddd2f0;
}
.kill-chip svg { width: 12px; height: 12px; fill: #c9a6ff; filter: drop-shadow(0 0 4px rgba(170,120,255,.7)); }
.icon-btn {
  width: 32px; height: 32px; display: grid; place-items: center;
  background: rgba(12,9,22,.74); border: 1px solid rgba(200,170,255,.2);
  border-radius: 4px; backdrop-filter: blur(4px);
  transition: background .15s, border-color .15s;
}
.icon-btn svg { width: 15px; height: 15px; fill: #d9ccf0; }
.icon-btn:hover { background: rgba(60,40,100,.8); border-color: rgba(200,170,255,.5); }

.boss-bar {
  width: min(560px, 92%); margin: 2px auto 0; padding: 5px 8px 6px;
  background: linear-gradient(180deg, rgba(22,10,18,.86), rgba(10,6,12,.9));
  border: 1px solid rgba(232,85,109,.35);
  border-radius: 4px;
  box-shadow: 0 0 22px rgba(180,30,60,.16), inset 0 0 20px rgba(0,0,0,.6);
  animation: bossIn .4s ease-out;
}
@keyframes bossIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
.boss-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; margin-bottom: 3px; }
.boss-head span:first-child {
  font-family: var(--serif); font-size: 11px; letter-spacing: .2em; color: #ffc2cb;
  text-shadow: 0 0 10px rgba(255,60,90,.5);
}
.boss-head span:last-child { font-family: var(--pixel); font-size: 8px; color: #a98c9e; }
.boss-track { height: 6px; background: #180a10; border-radius: 2px; overflow: hidden; border: 1px solid rgba(255,120,140,.15); }
.boss-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #6b0f22, #e8556d 60%, #ff9b8a); box-shadow: 0 0 10px rgba(255,70,90,.6); transition: width .12s linear; }

.toast {
  position: absolute; left: 50%; top: 23%; transform: translate(-50%, -8px);
  padding: 5px 18px; opacity: 0; pointer-events: none;
  font-family: var(--serif); font-size: 13px; letter-spacing: .24em; color: #f0e4ff;
  text-shadow: 0 0 14px rgba(170,120,255,.8), 0 2px 4px #000;
  background: linear-gradient(90deg, transparent, rgba(20,14,36,.72), transparent);
  border-top: 1px solid rgba(190,160,255,.25); border-bottom: 1px solid rgba(190,160,255,.25);
  transition: opacity .3s, transform .3s; white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

.hud-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; width: 100%; }
.health-block { display: flex; align-items: flex-end; gap: 7px; }
.portrait-frame {
  width: 38px; height: 42px; flex: 0 0 auto;
  background: radial-gradient(circle at 50% 30%, rgba(80,55,130,.55), rgba(8,6,14,.9));
  border: 1px solid rgba(190,165,255,.32);
  border-radius: 4px; overflow: hidden;
  box-shadow: 0 0 14px rgba(110,70,200,.2), inset 0 0 12px rgba(0,0,0,.7);
  display: grid; place-items: center;
}
#portrait { width: 32px; height: 36px; image-rendering: pixelated; }
.health-bars { display: flex; flex-direction: column; gap: 4px; min-width: 132px; }
.hp-track {
  position: relative; height: 15px; width: 100%;
  background: #12070d; border: 1px solid rgba(232,85,109,.4);
  border-radius: 3px; overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,.5), inset 0 1px 3px rgba(0,0,0,.8);
}
.hp-fill {
  height: 100%; width: 100%; background: var(--hp);
  box-shadow: 0 0 10px rgba(255,70,100,.4), inset 0 0 5px rgba(255,255,255,.28);
  transition: width .18s ease-out;
}
.hp-text {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-family: var(--pixel); font-size: 8px; font-weight: 700; letter-spacing: .06em;
  color: #ffe3e8; text-shadow: 0 1px 2px #3b0010;
}
.buff-row { display: flex; gap: 3px; min-height: 14px; }
.buff {
  display: flex; align-items: center; gap: 3px; padding: 1px 5px;
  font-size: 7px; font-weight: 700; letter-spacing: .06em;
  border: 1px solid rgba(255,255,255,.18); border-radius: 3px;
  background: rgba(20,14,34,.8); color: #fff;
}
.buff .t { font-family: var(--pixel); font-size: 7px; opacity: .8; }
.buff.fury { border-color: rgba(255,150,70,.6); color: #ffc89b; }
.buff.freeze { border-color: rgba(120,210,255,.6); color: #b8ecff; }
.buff.shield { border-color: rgba(240,210,120,.6); color: #ffe9b0; }
.buff.magnet { border-color: rgba(180,140,255,.6); color: #d9c2ff; }

.weapon-row { display: flex; gap: 4px; align-items: flex-end; }
.weapon-slot {
  position: relative; width: 34px; height: 34px;
  background: linear-gradient(180deg, rgba(26,20,42,.9), rgba(9,7,16,.92));
  border: 1px solid rgba(170,140,235,.24); border-radius: 4px;
  display: grid; place-items: center;
  box-shadow: 0 2px 6px rgba(0,0,0,.45);
  transition: border-color .2s, transform .2s;
}
.weapon-slot img, .weapon-slot canvas { width: 26px; height: 26px; image-rendering: pixelated; }
.weapon-slot .wlv {
  position: absolute; right: -3px; bottom: -3px;
  min-width: 13px; height: 12px; padding: 0 2px;
  display: grid; place-items: center;
  background: #1b142c; border: 1px solid rgba(190,160,255,.4); border-radius: 3px;
  font-family: var(--pixel); font-size: 7px; font-weight: 700; color: #d9c9ff;
}
.weapon-slot.evolved { border-color: rgba(242,201,107,.75); box-shadow: 0 0 12px rgba(242,201,107,.32); }
.weapon-slot.evolved .wlv { border-color: var(--gold); color: var(--gold); background: #2a1f10; }

.touch-hint {
  position: absolute; left: 50%; bottom: 18%; transform: translateX(-50%);
  font-size: 8px; letter-spacing: .24em; color: rgba(220,205,245,.5);
  animation: hintFade 4s ease forwards; pointer-events: none;
}
@keyframes hintFade { 0%,55% { opacity: .85; } 100% { opacity: 0; } }

/* floating joystick */
.joystick { position: absolute; width: 108px; height: 108px; margin: -54px 0 0 -54px; pointer-events: none; z-index: 20; }
.joy-base {
  position: absolute; inset: 0; border-radius: 50%;
  border: 1px solid rgba(190,165,255,.28);
  background: radial-gradient(circle, rgba(60,45,100,.18), rgba(10,8,18,.24) 70%);
  box-shadow: inset 0 0 20px rgba(0,0,0,.3), 0 0 18px rgba(130,90,255,.12);
}
.joy-stick {
  position: absolute; left: 50%; top: 50%; width: 42px; height: 42px; margin: -21px 0 0 -21px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #cdb8ff, #7b5cd6 55%, #3a2670);
  border: 1px solid rgba(255,255,255,.35);
  box-shadow: 0 0 16px rgba(150,110,255,.45), inset 0 0 8px rgba(255,255,255,.2);
  transition: transform .05s linear;
}

/* ============================== BUTTONS ============================== */
.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center;
  height: 42px; padding: 0 22px;
  font-family: var(--serif); font-weight: 600; font-size: 12px; letter-spacing: .2em;
  color: #e7dcf7;
  background: linear-gradient(180deg, rgba(46,36,70,.92), rgba(18,14,30,.95));
  border: 1px solid rgba(180,150,240,.28);
  border-radius: 3px;
  box-shadow: 0 3px 10px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.08);
  transition: transform .12s, box-shadow .2s, border-color .2s, background .2s;
  overflow: hidden;
}
.btn:hover { border-color: rgba(210,180,255,.65); background: linear-gradient(180deg, rgba(64,50,96,.95), rgba(24,18,40,.96)); box-shadow: 0 4px 18px rgba(90,60,160,.35); transform: translateY(-1px); }
.btn:active { transform: translateY(1px) scale(.995); }
.btn-primary {
  color: #fff7e3;
  background: linear-gradient(180deg, #8a5d24, #5b3a14 52%, #3a2410);
  border-color: rgba(242,201,107,.7);
  box-shadow: 0 3px 14px rgba(150,100,30,.35), inset 0 1px 0 rgba(255,235,180,.35);
}
.btn-primary:hover { background: linear-gradient(180deg, #a9762f, #74491b 52%, #4a2d12); border-color: #f2c96b; box-shadow: 0 4px 22px rgba(220,160,60,.4); }
.btn-ghost { background: rgba(18,14,30,.6); }
.btn-danger { color: #ffc7cf; border-color: rgba(232,85,109,.45); }
.btn-danger:hover { border-color: #e8556d; background: rgba(70,20,32,.7); }
.btn-small { height: 32px; padding: 0 14px; font-size: 10px; letter-spacing: .14em; }
.btn-hero {
  flex: 1; min-height: 56px; flex-direction: column; gap: 2px;
  background: linear-gradient(180deg, #b47a2b, #7a4c19 50%, #4b2c0d);
  border: 1px solid #f0c36a;
  box-shadow: 0 6px 26px rgba(190,130,40,.35), inset 0 1px 0 rgba(255,240,190,.5), inset 0 -12px 20px rgba(60,30,0,.4);
}
.btn-hero .btn-label { font-size: 16px; letter-spacing: .24em; text-shadow: 0 2px 0 #3c2208; }
.btn-hero .btn-sub { font-family: var(--sans); font-size: 7px; letter-spacing: .3em; color: rgba(255,235,190,.66); }
.btn-hero:hover { background: linear-gradient(180deg, #d19439, #925d20 50%, #5d370f); border-color: #ffe0a0; box-shadow: 0 8px 34px rgba(230,170,60,.45), inset 0 1px 0 rgba(255,245,205,.6); }
.btn-glint { position: absolute; top: 0; left: -60%; width: 40%; height: 100%; background: linear-gradient(100deg, transparent, rgba(255,255,255,.22), transparent); transform: skewX(-18deg); animation: glint 4s ease-in-out infinite; }
@keyframes glint { 0%, 55% { left: -60%; } 80%, 100% { left: 130%; } }

/* ============================== SCREENS ============================== */
.screen { position: absolute; inset: 0; z-index: 40; }
.overlay {
  display: flex; align-items: center; justify-content: center;
  background: rgba(4,3,9,.72);
  backdrop-filter: blur(5px);
  padding: calc(var(--safe-t) + 14px) 14px calc(var(--safe-b) + 14px);
  animation: overlayIn .22s ease-out;
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }

/* ---------- menu ---------- */
.menu-screen { z-index: 50; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.menu-shade {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 50% 30%, rgba(20,10,40,.15), rgba(4,2,10,.78) 78%),
    linear-gradient(180deg, rgba(4,2,10,.82) 0%, rgba(4,2,10,.18) 30%, rgba(4,2,10,.4) 66%, rgba(4,2,10,.92) 100%);
}
.menu-inner {
  position: relative; z-index: 1; width: min(1000px, 100%); height: 100%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: clamp(14px, 3.2vh, 34px);
  padding: 14px 0;
}
.brand { text-align: center; display: flex; flex-direction: column; align-items: center; gap: 4px; animation: brandIn .9s cubic-bezier(.2,.8,.2,1) both; }
@keyframes brandIn { from { opacity: 0; transform: translateY(-14px) scale(.97); } to { opacity: 1; transform: none; } }
.brand-mark { width: 34px; height: 34px; color: #b98cff; filter: drop-shadow(0 0 12px rgba(160,110,255,.7)); animation: markPulse 5s ease-in-out infinite; }
.brand-mark svg { width: 100%; height: 100%; }
@keyframes markPulse { 0%,100% { filter: drop-shadow(0 0 10px rgba(160,110,255,.55)); } 50% { filter: drop-shadow(0 0 20px rgba(190,150,255,.9)); } }
.game-title {
  margin: 0;
  font-family: var(--serif); font-size: clamp(42px, 7.4vw, 84px); line-height: .94;
  font-weight: 700; letter-spacing: .12em; text-indent: .12em;
  color: #f1e6ff;
  text-shadow:
    0 0 24px rgba(150,100,255,.55),
    0 0 70px rgba(100,60,200,.35),
    0 3px 0 #1b1230, 0 6px 18px rgba(0,0,0,.9);
  background: linear-gradient(180deg, #fff8ea 8%, #e6d6ff 38%, #a985e8 70%, #6b4aa8 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 2px 0 rgba(20,10,40,.8));
}
.tagline {
  margin: 0; font-size: clamp(7px, 1.1vw, 10px); letter-spacing: .34em; color: #a99bc4;
  text-transform: uppercase;
}
.tagline .dot { color: #7a5bc0; }

.menu-panel { width: min(880px, 100%); display: flex; flex-direction: column; gap: 12px; animation: panelIn .8s .1s cubic-bezier(.2,.8,.2,1) both; }
@keyframes panelIn { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
.panel-label { display: flex; align-items: center; gap: 12px; font-size: 8px; letter-spacing: .3em; color: #988ab2; }
.panel-label .rule { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(160,130,220,.32), transparent); }

.char-select { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.char-card {
  position: relative; display: flex; align-items: center; gap: 8px;
  min-height: 78px; padding: 7px 9px;
  text-align: left;
  background: linear-gradient(160deg, rgba(30,24,48,.82), rgba(10,8,18,.9));
  border: 1px solid rgba(150,125,210,.22);
  border-radius: 4px;
  transition: transform .16s, border-color .16s, box-shadow .2s, background .2s;
  overflow: hidden;
}
.char-card::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(120deg, transparent 55%, rgba(255,255,255,.05));
}
.char-card:hover { transform: translateY(-2px); border-color: rgba(190,160,255,.5); background: linear-gradient(160deg, rgba(44,34,68,.9), rgba(14,10,24,.92)); }
.char-card.selected { border-color: var(--gold); box-shadow: 0 0 0 1px rgba(242,201,107,.25), 0 0 22px rgba(200,150,60,.16), inset 0 0 24px rgba(180,130,50,.08); background: linear-gradient(160deg, rgba(54,40,42,.85), rgba(16,11,18,.94)); }
.char-card.selected::before {
  content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--gold);
  box-shadow: 0 0 10px rgba(242,201,107,.8);
}
.char-portrait {
  position: relative; width: 46px; height: 58px; flex: 0 0 auto;
  display: grid; place-items: center;
  background: radial-gradient(circle at 50% 35%, var(--glow, rgba(120,90,200,.4)), rgba(5,4,10,.85) 75%);
  border: 1px solid rgba(255,255,255,.08); border-radius: 3px;
  overflow: hidden;
}
.char-portrait canvas { width: 34px; height: 42px; image-rendering: pixelated; transform: translateY(3px); }
.char-info { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.char-name { font-family: var(--serif); font-size: 12px; letter-spacing: .12em; color: #f0e8ff; white-space: nowrap; }
.char-role { font-size: 6.5px; letter-spacing: .18em; color: var(--accent, #b49bff); text-transform: uppercase; }
.char-weapon { display: flex; align-items: center; gap: 4px; font-size: 7px; color: #9387ab; letter-spacing: .04em; }
.char-weapon img { width: 13px; height: 13px; image-rendering: pixelated; }
.char-perk { font-size: 7px; color: #7d728f; line-height: 1.3; }

.menu-actions { display: flex; gap: 8px; align-items: stretch; }
.menu-side { display: flex; flex-direction: column; gap: 8px; width: 158px; }
.menu-side .btn { flex: 1; height: auto; min-height: 24px; font-size: 9px; }
.menu-foot { display: flex; align-items: center; justify-content: center; gap: 10px; font-size: 6.5px; letter-spacing: .2em; color: #6f6484; }
.menu-foot .sep { color: #4d3f68; }

/* ---------- level up ---------- */
#levelup { z-index: 60; }
.overlay-glow {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 60% 50% at 50% 45%, rgba(120,80,230,.18), transparent 70%);
  animation: glowPulse 2.6s ease-in-out infinite;
}
@keyframes glowPulse { 0%,100% { opacity: .7; } 50% { opacity: 1; } }
.levelup-inner { position: relative; width: min(920px, 100%); display: flex; flex-direction: column; align-items: center; gap: 14px; }
.levelup-head { text-align: center; display: flex; flex-direction: column; align-items: center; gap: 2px; }
.lvl-sigil { color: var(--gold); font-size: 18px; text-shadow: 0 0 16px rgba(242,201,107,.8); animation: sigilSpin 6s linear infinite; }
@keyframes sigilSpin { 0%,100% { transform: rotate(0deg) scale(1); } 50% { transform: rotate(180deg) scale(1.15); } }
.levelup-head h2 { margin: 0; font-family: var(--serif); font-size: clamp(22px, 3.4vw, 34px); letter-spacing: .18em; color: #fff3d5; text-shadow: 0 0 24px rgba(242,201,107,.4), 0 2px 0 #2a1c08; }
.levelup-head h2 span { color: var(--gold); }
.levelup-head p { margin: 0; font-size: 8px; letter-spacing: .34em; color: #a495c1; }

.upgrade-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; width: 100%; }
.upgrade-card {
  position: relative; display: flex; flex-direction: column; gap: 7px;
  padding: 13px 13px 11px; min-height: 190px;
  text-align: left;
  background: linear-gradient(165deg, rgba(30,25,48,.96), rgba(10,8,18,.98));
  border: 1px solid var(--rarity-edge, rgba(150,125,210,.3));
  border-radius: 5px;
  box-shadow: 0 10px 30px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.06);
  overflow: hidden;
  animation: cardIn .32s cubic-bezier(.2,.9,.3,1.2) both;
  transition: transform .16s, box-shadow .2s, border-color .2s;
}
.upgrade-card:nth-child(2) { animation-delay: .05s; }
.upgrade-card:nth-child(3) { animation-delay: .1s; }
@keyframes cardIn { from { opacity: 0; transform: translateY(18px) scale(.97); } to { opacity: 1; transform: none; } }
.upgrade-card::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: var(--rarity-edge, #8a7aa8);
  box-shadow: 0 0 14px var(--rarity-edge, #8a7aa8);
}
.upgrade-card::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, var(--rarity-glow, rgba(140,110,220,.1)), transparent 70%);
}
.upgrade-card:hover { transform: translateY(-3px); border-color: var(--rarity-edge, #b9a3ef); box-shadow: 0 16px 40px rgba(0,0,0,.65), 0 0 24px var(--rarity-glow, rgba(140,110,220,.18)); }
.upgrade-card:focus-visible { outline: 2px solid var(--rarity-edge, #fff); outline-offset: 2px; }
.upgrade-card .card-key {
  position: absolute; right: 8px; top: 8px;
  width: 16px; height: 16px; display: grid; place-items: center;
  font-family: var(--pixel); font-size: 8px; color: #7f7399;
  border: 1px solid rgba(255,255,255,.1); border-radius: 3px;
}
.upgrade-card .card-top { display: flex; align-items: center; gap: 9px; position: relative; z-index: 1; }
.card-icon {
  width: 42px; height: 42px; flex: 0 0 auto; display: grid; place-items: center;
  background: radial-gradient(circle, rgba(90,70,140,.3), rgba(8,6,14,.7));
  border: 1px solid rgba(255,255,255,.08); border-radius: 4px;
}
.card-icon canvas, .card-icon img { width: 32px; height: 32px; image-rendering: pixelated; }
.card-name { font-family: var(--serif); font-size: 14px; letter-spacing: .06em; color: #f4ecff; line-height: 1.15; }
.card-sub { font-size: 7px; letter-spacing: .16em; color: var(--rarity-edge, #a99bc4); text-transform: uppercase; }
.card-tag { display: inline-flex; align-items: center; gap: 4px; margin-top: 1px; font-size: 6.5px; letter-spacing: .14em; color: #8e82a6; }
.card-desc { position: relative; z-index: 1; font-size: 9px; line-height: 1.5; color: #b8adcb; flex: 1; }
.card-desc b { color: #efe6ff; font-weight: 600; }
.card-pips { display: flex; gap: 2px; margin-top: auto; position: relative; z-index: 1; }
.card-pips i { width: 12px; height: 3px; border-radius: 1px; background: rgba(255,255,255,.1); }
.card-pips i.on { background: var(--rarity-edge, #a77bff); box-shadow: 0 0 6px var(--rarity-glow, rgba(167,123,255,.5)); }
.card-rarity {
  position: absolute; left: 13px; bottom: 9px; font-size: 6px; letter-spacing: .22em; color: var(--rarity-edge, #8a7aa8);
  text-transform: uppercase; opacity: .85;
}
.upgrade-card .card-pips { margin-bottom: 9px; }
.levelup-foot { display: flex; align-items: center; gap: 16px; }
.levelup-foot .hint { font-size: 7px; letter-spacing: .24em; color: #716683; }
.reroll-count {
  display: inline-grid; place-items: center; min-width: 14px; height: 13px; padding: 0 3px;
  background: rgba(242,201,107,.15); border: 1px solid rgba(242,201,107,.35); border-radius: 3px;
  font-family: var(--pixel); font-size: 8px; color: var(--gold); margin-left: 3px;
}
.rarity-common { --rarity-edge: #8d83a3; --rarity-glow: rgba(140,130,170,.18); }
.rarity-rare { --rarity-edge: #6fa8ff; --rarity-glow: rgba(90,150,255,.28); }
.rarity-epic { --rarity-edge: #b98cff; --rarity-glow: rgba(160,100,255,.3); }
.rarity-legend { --rarity-edge: #f2c96b; --rarity-glow: rgba(242,201,107,.35); }
.rarity-legend .card-name { color: #ffe9b0; text-shadow: 0 0 16px rgba(242,201,107,.4); }

/* ---------- modals ---------- */
.modal-card {
  width: min(520px, 100%);
  max-height: calc(100vh - 28px);
  overflow: auto;
  padding: 24px 24px 20px;
  background: linear-gradient(165deg, rgba(24,19,40,.98), rgba(9,7,16,.99));
  border: 1px solid rgba(180,150,240,.3);
  border-radius: 5px;
  box-shadow: 0 30px 80px rgba(0,0,0,.7), inset 0 1px 0 rgba(255,255,255,.07), 0 0 60px rgba(100,70,180,.1);
  animation: modalIn .26s cubic-bezier(.2,.9,.3,1.1);
  scrollbar-width: thin;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
.modal-head { text-align: center; margin-bottom: 18px; }
.modal-head h2 { margin: 0 0 4px; font-family: var(--serif); font-size: 26px; letter-spacing: .18em; color: #f2e9ff; text-shadow: 0 0 20px rgba(150,110,255,.3); }
.modal-head p { margin: 0; font-size: 7px; letter-spacing: .3em; color: #8d7fa8; }
.modal-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 18px; }
.run-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 7px; margin: 4px 0 6px; }
.stat-cell {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 8px 10px; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.06); border-radius: 3px;
}
.stat-cell .k { font-size: 7px; letter-spacing: .18em; color: #887c9f; text-transform: uppercase; }
.stat-cell .v { font-family: var(--pixel); font-size: 11px; font-weight: 700; color: #ece2ff; }

.settings-card { width: min(460px, 100%); }
.settings-list { display: flex; flex-direction: column; gap: 2px; }
.setting-row {
  display: grid; grid-template-columns: 1fr 130px 32px; align-items: center; gap: 10px;
  min-height: 44px; padding: 5px 2px;
  border-bottom: 1px solid rgba(255,255,255,.055);
  font-size: 10px; color: #cfc4e2;
}
.setting-row:last-child { border-bottom: 0; }
.setting-row output { font-family: var(--pixel); font-size: 9px; color: #a99bc4; text-align: right; }
.setting-row select, .select {
  width: 100%; height: 30px; padding: 0 8px;
  background: #151022; color: #d9ccf0; border: 1px solid rgba(180,150,240,.25); border-radius: 3px;
  font-size: 10px; font-family: var(--sans);
}
input[type="range"] {
  -webkit-appearance: none; appearance: none; width: 100%; height: 4px; border-radius: 2px;
  background: linear-gradient(90deg, #7b5cd6, #2a1f45); outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #e8dcff, #8f6fe0 60%, #4a3288);
  border: 1px solid rgba(255,255,255,.4); box-shadow: 0 0 10px rgba(150,110,255,.5); cursor: pointer;
}
input[type="range"]::-moz-range-thumb { width: 14px; height: 14px; border: 1px solid #fff6; border-radius: 50%; background: #9b7bea; }
.switch { justify-self: end; appearance: none; width: 38px; height: 20px; border-radius: 10px; background: #241a38; border: 1px solid rgba(180,150,240,.25); position: relative; cursor: pointer; transition: background .2s; }
.switch::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: #7d6a9e; transition: transform .18s, background .18s; }
.switch:checked { background: #4b3287; border-color: rgba(190,160,255,.6); }
.switch:checked::after { transform: translateX(18px); background: #d8c4ff; box-shadow: 0 0 8px rgba(190,150,255,.8); }

.how-card { width: min(620px, 100%); }
.how-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.how-item { padding: 10px; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.06); border-radius: 3px; }
.how-item .key { display: inline-block; padding: 2px 7px; margin-bottom: 5px; font-family: var(--pixel); font-size: 8px; letter-spacing: .1em; color: #e7d8ff; background: rgba(130,95,220,.18); border: 1px solid rgba(170,140,240,.35); border-radius: 2px; }
.how-item p { margin: 0; font-size: 9px; line-height: 1.55; color: #a99cbe; }

/* ---------- end screen ---------- */
#end { z-index: 70; flex-direction: column; }
.end-glow {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 55% 55% at 50% 40%, rgba(120,20,50,.22), transparent 70%);
}
#end.victory .end-glow { background: radial-gradient(ellipse 60% 55% at 50% 40%, rgba(220,170,60,.2), transparent 70%); }
.end-inner { position: relative; width: min(500px, 100%); text-align: center; display: flex; flex-direction: column; align-items: center; gap: 6px; animation: modalIn .4s cubic-bezier(.2,.9,.3,1.1); }
.end-sigil { font-size: 38px; color: var(--blood); text-shadow: 0 0 26px rgba(232,85,109,.7); line-height: 1; }
#end.victory .end-sigil { color: var(--gold); text-shadow: 0 0 30px rgba(242,201,107,.8); }
.end-inner h2 { margin: 0; font-family: var(--serif); font-size: clamp(34px, 5.5vw, 56px); letter-spacing: .14em; color: #f3e8ff; text-shadow: 0 0 30px rgba(200,60,90,.35), 0 3px 0 #1b0c16; }
#end.victory .end-inner h2 { color: #fff0c4; text-shadow: 0 0 34px rgba(242,201,107,.5), 0 3px 0 #2a1c08; }
#endSubtitle { margin: 0; font-size: 9px; letter-spacing: .16em; color: #9c8fb4; }
.end-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; width: 100%; margin: 14px 0 8px; }
.end-stat { padding: 9px 4px; background: rgba(255,255,255,.03); border: 1px solid rgba(255,255,255,.07); border-radius: 3px; }
.end-stat .k { display: block; font-size: 6px; letter-spacing: .2em; color: #7f7395; margin-bottom: 3px; }
.end-stat .v { font-family: var(--pixel); font-size: 14px; font-weight: 700; color: #f0e6ff; }
.end-actions { display: flex; gap: 8px; margin-top: 8px; }
.end-actions .btn { min-width: 140px; }
.new-best { margin: 8px 0 0; font-size: 8px; letter-spacing: .28em; color: var(--gold); animation: bestPulse 1.6s ease-in-out infinite; }
@keyframes bestPulse { 0%,100% { opacity: .6; } 50% { opacity: 1; text-shadow: 0 0 14px rgba(242,201,107,.8); } }

.rotate-hint {
  position: fixed; left: 50%; bottom: calc(var(--safe-b) + 16px); transform: translateX(-50%);
  z-index: 80; padding: 6px 12px; font-size: 8px; letter-spacing: .12em; color: #cfc2e6;
  background: rgba(10,8,18,.85); border: 1px solid rgba(170,140,240,.3); border-radius: 3px;
  pointer-events: none;
}

/* ============================== RESPONSIVE ============================== */
@media (max-width: 820px) {
  .char-select { grid-template-columns: repeat(2, 1fr); gap: 6px; }
  .char-card { min-height: 64px; padding: 5px 7px; }
  .char-portrait { width: 36px; height: 46px; }
  .char-portrait canvas { width: 27px; height: 34px; }
  .char-name { font-size: 11px; }
  .char-perk { display: none; }
  .menu-actions { flex-direction: column; }
  .menu-side { flex-direction: row; width: 100%; }
  .menu-side .btn { height: 34px; }
  .menu-inner { gap: 16px; }
  .brand-mark { width: 26px; height: 26px; }
  .upgrade-cards { grid-template-columns: 1fr; gap: 6px; }
  .upgrade-card { min-height: 0; padding: 10px 11px; flex-direction: row; align-items: center; gap: 9px; }
  .upgrade-card .card-top { flex: 0 0 auto; }
  .card-desc { font-size: 8px; }
  .card-pips, .card-rarity { display: none; }
  .card-icon { width: 36px; height: 36px; }
  .card-icon canvas { width: 28px; height: 28px; }
  .card-name { font-size: 12px; }
  .card-key { display: none; }
  .levelup-inner { gap: 9px; }
  .levelup-foot .hint { display: none; }
  .upgrade-card .card-desc { max-height: 42px; overflow: hidden; }
  .how-grid { grid-template-columns: 1fr; }
  .end-stats { grid-template-columns: repeat(2, 1fr); }
  .modal-card { padding: 18px 16px 16px; }
  .setting-row { grid-template-columns: 1fr 110px 30px; }
  .hud-bottom { gap: 6px; }
  .weapon-slot { width: 29px; height: 29px; }
  .weapon-slot img, .weapon-slot canvas { width: 22px; height: 22px; }
  .health-bars { min-width: 108px; }
  .timer { font-size: 24px; }
  .zone-name { font-size: 6.5px; }
  .toast { font-size: 10px; top: 20%; }
}
@media (max-height: 560px) {
  .menu-inner { gap: 8px; }
  .brand-mark { display: none; }
  .game-title { font-size: 38px; }
  .tagline { font-size: 6px; }
  .char-card { min-height: 54px; }
  .char-portrait { width: 32px; height: 40px; }
  .char-portrait canvas { width: 24px; height: 30px; }
  .char-perk { display: none; }
  .menu-panel { gap: 6px; }
  .menu-side { flex-direction: row; }
  .menu-side .btn { height: 28px; }
  .btn-hero { min-height: 46px; }
  .upgrade-card { min-height: 0; }
}
@media (min-width: 900px) and (min-height: 700px) {
  .upgrade-card { min-height: 210px; }
}

