  add('magnet', drawMap(MAGNET, { o: '#1a0c0c', r: '#e8556d' }));
  add('fury', drawMap(FURY, { o: '#200a04', y: '#ffb03a', r: '#ff5a2e' }));
  add('crown', drawMap(mapFrom([
    'o..o..o..o',
    'oyoyoyoyyo',
