712: export function drawSprite(g, key, x, y, scale = 1, flip = false, alpha = 1) {
713:   const s = SPRITES[key];
714:   if (!s) return;
715:   const w = s.width * scale, h = s.height * scale;
716:   g.save();
717:   g.globalAlpha *= alpha;
718:   g.translate(Math.round(x), Math.round(y));
719:   if (flip) g.scale(-1, 1);
720:   g.drawImage(s, Math.round(-w / 2), Math.round(-h), w, h);
721:   g.restore();
722: }
