import { CHARACTERS, WEAPONS, PASSIVES, ENEMIES, BOSSES, POWERUPS, BUFF_META, BIOMES, WAVE_NAMES, gemSpriteFor, xpNeeded, weaponStat, weaponUpgradeText } from './data.js';
import { World } from './world.js';
import { drawSprite, iconURL, portraitFor } from './sprites.js';
import { AudioEngine } from './audio.js';

const $ = id => document.getElementById(id);
const canvas = $('game'), ctx = canvas.getContext('2d');
ctx.imageSmoothingEnabled = false;
const audio = new AudioEngine();
const world = new World(417);
const ui = Object.fromEntries(['hud','menu','levelup','pause','settings','how','end','charSelect','startBtn','pauseBtn','resumeBtn','restartBtn','quitBtn','settingsBtn','pauseSettingsBtn','settingsClose','howBtn','howClose','retryBtn','endMenuBtn','upgradeCards','rerollBtn','rerollCount','xpFill','levelNum','lvlNum','timer','zoneName','killCount','hpFill','hpText','weaponRow','buffRow','bossBar','bossName','bossFill','bossHpText','toast','portrait','pauseStats','endStats','newBest','bestRecord','musicVol','sfxVol','musicVolOut','sfxVolOut','shakeToggle','dmgToggle','qualitySelect','joystickSelect','joystick','stick','touchHint','rotateHint','endTitle','endSubtitle','endSigil'].map(id=>[id,$(id)]));
const settingDefaults={music:55,sfx:80,shake:true,damage:true,quality:'high',joystick:'auto'};
let settings={...settingDefaults};
try { settings={...settings,...JSON.parse(localStorage.getItem('gravewake-settings')||'{}')}; } catch {}
let selected=0, state='menu', run=null, last=0, raf=0, toastTimer=0, keys=new Set(), touch=null, dpr=1, vw=0, vh=0, particles=[], floating=[];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), rand=(a,b)=>a+Math.random()*(b-a), pick=a=>a[Math.floor(Math.random()*a.length)], dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), norm=(x,y)=>{const l=Math.hypot(x,y)||1;return [x/l,y/l]};

function resize(){ dpr=Math.min(devicePixelRatio||1,2); vw=innerWidth; vh=innerHeight; canvas.width=Math.floor(vw*dpr); canvas.height=Math.floor(vh*dpr); canvas.style.width=vw+'px'; canvas.style.height=vh+'px'; ctx.setTransform(dpr,0,0,dpr,0,0); ctx.imageSmoothingEnabled=false; }
addEventListener('resize',resize); resize();
function saveSettings(){localStorage.setItem('gravewake-settings',JSON.stringify(settings));}
function show(el,on=true){el?.classList.toggle('hidden',!on)}
function say(text, duration=2.3){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),duration*1000)}
function formatTime(s){const n=Math.floor(s);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function setScreen(screen){for(const id of ['menu','levelup','pause','settings','how','end'])show(ui[id],id===screen);}

function makeCharacterCards(){ui.charSelect.innerHTML='';CHARACTERS.forEach((c,i)=>{const b=document.createElement('button');b.className='char-card'+(i===selected?' selected':'');b.setAttribute('role','radio');b.setAttribute('aria-checked',i===selected?'true':'false');b.innerHTML=`<canvas width="36" height="42"></canvas><span class="char-name">${c.name}</span><span class="char-title">${c.title}</span><span class="char-perk">${c.perk}</span>`;const p=b.querySelector('canvas').getContext('2d');p.imageSmoothingEnabled=false;p.drawImage(portraitFor(c.id,36,42),0,0);b.addEventListener('click',()=>{selected=i;makeCharacterCards();audio.play?.('click')});ui.charSelect.appendChild(b);});}
makeCharacterCards();

function createRun(){const c=CHARACTERS[selected];run={time:0,kills:0,level:1,xp:0,next:xpNeeded(1),player:{x:0,y:0,vx:0,vy:0,r:7,hp:c.hp,maxHp:c.hp,speed:82*c.speed,armor:c.armor,charSpeed:c.speed,charArea:c.area,charCooldown:c.cooldown,magnet:c.magnet,stats:{},weapons:[{id:c.weapon,level:1,evolved:false,cd:0}],invuln:0,damageFlash:0,anim:0,facing:1},enemies:[],gems:[],shots:[],zones:[],drops:[],boss:null,spawn:0,powerup:0,killGoal:0,rerolls:1,buffs:{},shake:0,biome:-1,damageNumbers:settings.damage,elapsed:0,dead:false};particles=[];floating=[];state='playing';setScreen(null);show(ui.hud,true);audio.ensure();audio.startMusic();audio.setIntensity(0.15);ui.portrait.getContext('2d').drawImage(portraitFor(c.id,32,36),0,0);say(`${c.name} enters the Hollow Grove`);updateHud();last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);}
function togglePause(){if(state==='playing'){state='paused';setScreen('pause');audio.duck(true);ui.pauseStats.innerHTML=statsMarkup();}else if(state==='paused'){state='playing';setScreen(null);audio.duck(false);last=performance.now();}}
function statsMarkup(){return `<div><span>TIME SURVIVED</span><b>${formatTime(run.time)}</b></div><div><span>FOES SLAIN</span><b>${run.kills}</b></div><div><span>LEVEL</span><b>${run.level}</b></div>`;}
function beginEnd(win){state=win?'victory':'defeat';setScreen('end');show(ui.hud,false);audio.stopMusic();audio.play(win?'victory':'defeat');ui.endTitle.textContent=win?'DAWN BREAKS':'YOU FELL';ui.endSubtitle.textContent=win?'The Umbral Tide recedes. You have survived the night.':'The Umbral Tide takes another soul.';ui.endSigil.textContent=win?'✦':'☠';ui.endStats.innerHTML=statsMarkup()+`<div><span>SOULS GATHERED</span><b>${run.xp}</b></div>`;const best=Number(localStorage.getItem('gravewake-best')||0);const score=Math.floor(run.time);if(score>best){localStorage.setItem('gravewake-best',score);show(ui.newBest,true);}else show(ui.newBest,false);updateBest();}
function updateBest(){const b=Number(localStorage.getItem('gravewake-best')||0);ui.bestRecord.textContent=b?`BEST RUN · ${formatTime(b)}`:'NO RUNS YET';}
updateBest();

function startLevelUp(){if(state!=='playing')return;state='levelup';audio.duck(true);audio.play('level');ui.lvlNum.textContent=run.level;const opts=buildChoices();ui.upgradeCards.innerHTML='';opts.forEach((o,i)=>{const card=document.createElement('button');card.className=`upgrade-card rarity-${o.rarity||'common'}`;card.innerHTML=`<span class="card-number">0${i+1}</span><img src="${iconURL(o.icon)}"><span class="card-type">${o.tag}</span><strong>${o.name}</strong><span class="card-desc">${o.desc}</span><span class="card-action">${o.action}</span>`;card.addEventListener('click',()=>chooseUpgrade(o));ui.upgradeCards.appendChild(card);});setScreen('levelup');}
function buildChoices(){const all=[];for(const w of run.player.weapons){if(w.level<8&&!w.evolved){const d=WEAPONS[w.id];all.push({kind:'weapon',id:w.id,name:d.name,icon:d.icon,tag:'WEAPON · LV '+w.level,desc:d.desc,action:weaponUpgradeText(w),rarity:w.level>=6?'rare':'common'});}else if(w.level>=8&&!w.evolved&&run.player.stats[WEAPONS[w.id].evo.passive])all.push({kind:'evolve',id:w.id,name:WEAPONS[w.id].evoName,icon:WEAPONS[w.id].icon,tag:'EVOLUTION',desc:WEAPONS[w.id].evo.text,action:'EVOLVE WEAPON',rarity:'legend'});}
