20: function valueNoise(x, y, seed = 0) {
21:   const xi = Math.floor(x), yi = Math.floor(y);
22:   const xf = smooth(x - xi), yf = smooth(y - yi);
23:   const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed);
24:   const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed);
25:   return (a + (b - a) * xf) * (1 - yf) + (c + (d - c) * xf) * yf;
