function gainXp(value){run.xp+=Math.ceil(value*(1+(run.player.stats.growth||0)*.1));while(run.xp>=run.next){run.xp-=run.next;run.level++;run.next=xpNeeded(run.level);startLevelUp();break;}updateHud();}
function nearest(x,y,max=Infinity,skip=new Set()){let best=null,bd=max;for(const e of run.enemies){if(e.dead||skip.has(e))continue;const d=Math.hypot(e.x-x,e.y-y);if(d<bd){bd=d;best=e;}}if(run.boss){const d=Math.hypot(run.boss.x-x,run.boss.y-y);if(d<bd)best=run.boss;}return best;}
function hitCircle(x,y,r,damage){for(const e of run.enemies)if(!e.dead&&Math.hypot(e.x-x,e.y-y)<r+e.r)damageEnemy(e,damage);if(run.boss&&Math.hypot(run.boss.x-x,run.boss.y-y)<r+run.boss.r)damageEnemy(run.boss,damage);}
function castWeapon(w,dt){const p=run.player,d=WEAPONS[w.id],s=weaponStat(w,p);w.cd-=dt;if(d.type==='orbit'||d.type==='aura'){if(w.cd<=0){w.cd=s.cooldown;const count=d.type==='orbit'?s.amount:1;for(let i=0;i<count;i++){const a=run.time*3+i*Math.PI*2/count,x=p.x+Math.cos(a)*(d.type==='orbit'?s.radius:0),y=p.y+Math.sin(a)*(d.type==='orbit'?s.radius:0);hitCircle(x,y,d.type==='orbit'?10: s.radius,s.damage);}}return;}if(w.cd>0)return;w.cd=s.cooldown;const target=nearest(p.x,p.y,s.range||300);if(!target)return;const [dx,dy]=norm(target.x-p.x,target.y-p.y);p.facing=dx<0?-1:1;const count=s.amount||1;
 if(d.type==='melee'){for(let i=0;i<count;i++){const a=Math.atan2(dy,dx)+(i-(count-1)/2)*.22;for(const e of run.enemies){const ex=e.x-p.x,ey=e.y-p.y,dd=Math.hypot(ex,ey),da=Math.atan2(ey,ex)-a;if(dd<s.range&&Math.abs(Math.atan2(Math.sin(da),Math.cos(da)))<s.arc/2)damageEnemy(e,s.damage,w.evolved?'crit':'attack');}if(run.boss&&Math.hypot(run.boss.x-p.x,run.boss.y-p.y)<s.range)damageEnemy(run.boss,s.damage);}particles.push({x:p.x+dx*28,y:p.y+dy*28,life:.2,max:.2,color:d.color,size:30,slash:true,angle:Math.atan2(dy,dx)});}
 else if(d.type==='lightning'){let cur=target,hit=new Set();for(let i=0;i<count;i++){if(!cur)break;damageEnemy(cur,s.damage,w.evolved?'crit':'attack');hit.add(cur);let next=null,bd=s.range*.65;for(const e of run.enemies){const dd=Math.hypot(e.x-cur.x,e.y-cur.y);if(!e.dead&&!hit.has(e)&&dd<bd){next=e;bd=dd;}}cur=next;}particles.push({x:target.x,y:target.y,life:.22,max:.22,color:d.color,size:20,flash:true});}
 else if(d.type==='zone'){const z={x:target.x,y:target.y,r:s.radius,damage:s.damage,life:s.duration,cd:0,color:d.color};run.zones.push(z);}
 else {for(let i=0;i<count;i++){const spread=(i-(count-1)/2)*.12,a=Math.atan2(dy,dx)+spread;run.shots.push({x:p.x,y:p.y,vx:Math.cos(a)*s.speed,vy:Math.sin(a)*s.speed,damage:s.damage,life:(s.range||300)/s.speed,r:d.type==='explosive'?6:3,pierce:s.pierce||1,color:d.color,explosive:d.type==='explosive',area:s.radius||28});}}}
function update(dt){if(!run||state!=='playing')return;const p=run.player;run.time+=dt;run.elapsed+=dt;run.spawn-=dt;run.powerup-=dt;if(run.spawn<=0){spawnEnemy();run.spawn=Math.max(.16,.85-run.time/260)+Math.random()*.25;}if(run.time>=300*(run.bosses||0+1)){/* boss timing handled below */}if(!run.boss&&run.time>=((run.bosses||0)+1)*300){run.bosses=(run.bosses||0)+1;spawnBoss();}if(run.time>=1800){beginEnd(true);return;}if(run.powerup<=0&&run.time>30){run.drops.push({x:p.x+rand(-260,260),y:p.y+rand(-220,220),type:pick(Object.keys(POWERUPS)),r:8});run.powerup=48;}
 const [ix,iy]=inputVector();p.vx=ix*p.speed;p.vy=iy*p.speed;p.x+=p.vx*dt;p.y+=p.vy*dt;if(ix||iy)p.anim+=dt*9;p.invuln=Math.max(0,p.invuln-dt);p.damageFlash=Math.max(0,p.damageFlash-dt);if(p.regen)p.hp=Math.min(p.maxHp,p.hp+p.regen*dt);for(const k of Object.keys(run.buffs))run.buffs[k]=Math.max(0,run.buffs[k]-dt);
 for(const e of run.enemies){if(e.dead)continue;e.anim+=dt*7;e.slow=Math.max(0,e.slow-dt);let dx=p.x-e.x,dy=p.y-e.y,dd=Math.hypot(dx,dy)||1;if(e.ranged&&dd<e.ranged){e.cd-=dt;if(e.cd<=0){run.shots.push({x:e.x,y:e.y,vx:dx/dd*105,vy:dy/dd*105,damage:e.dmg,life:3,r:4,color:'#d78cff',enemyShot:true});e.cd=e.shotCd;}}else{e.x+=dx/dd*e.speed*dt*(e.slow?0.35:1);e.y+=dy/dd*e.speed*dt*(e.slow?0.35:1);}if(dd<p.r+e.r)hurt(e.dmg*dt*1.6);}
 if(run.boss){const b=run.boss,dx=p.x-b.x,dy=p.y-b.y,dd=Math.hypot(dx,dy)||1;b.x+=dx/dd*b.speed*dt;b.y+=dy/dd*b.speed*dt;b.cd-=dt;if(b.cd<=0){run.zones.push({x:p.x,y:p.y,r:42,life:.85,damage:0,enemy:true,color:'#d65a8a'});b.cd=2.6;}if(dd<p.r+b.r)hurt(b.dmg*dt);}
 for(const w of p.weapons)castWeapon(w,dt);
 for(const z of run.zones){z.life-=dt;z.cd=(z.cd||0)-dt;if(z.enemy){if(z.life<.6&&Math.hypot(p.x-z.x,p.y-z.y)<z.r+p.r)hurt(16);}else if(z.cd<=0){hitCircle(z.x,z.y,z.r,z.damage);z.cd=.5;}}run.zones=run.zones.filter(z=>z.life>0);
 for(const s of run.shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.enemyShot){if(Math.hypot(p.x-s.x,p.y-s.y)<p.r+s.r){hurt(s.damage);s.life=0;}}else{for(const e of run.enemies){if(!e.dead&&Math.hypot(e.x-s.x,e.y-s.y)<e.r+s.r){if(s.explosive)hitCircle(s.x,s.y,s.area,s.damage);else damageEnemy(e,s.damage);s.pierce--;if(s.pierce<=0){s.life=0;break;}}}if(run.boss&&Math.hypot(run.boss.x-s.x,run.boss.y-s.y)<run.boss.r+s.r){damageEnemy(run.boss,s.damage);s.life=0;}}}run.shots=run.shots.filter(s=>s.life>0);run.enemies=run.enemies.filter(e=>!e.dead);
 for(const g of run.gems){g.x+=g.vx*dt;g.y+=g.vy*dt;g.vx*=Math.pow(.08,dt);g.vy*=Math.pow(.08,dt);let dx=p.x-g.x,dy=p.y-g.y,dd=Math.hypot(dx,dy);if(run.buffs.magnet>0||dd<84*p.magnet){g.vx+=dx/(dd||1)*260*dt;g.vy+=dy/(dd||1)*260*dt;}if(dd<p.r+8){gainXp(g.value);g.got=true;audio.play('pickup');}}run.gems=run.gems.filter(g=>!g.got);
 for(const d of run.drops){if(Math.hypot(p.x-d.x,p.y-d.y)<p.r+d.r+3){const info=POWERUPS[d.type];if(d.type==='heart')p.hp=Math.min(p.maxHp,p.hp+p.maxHp*.3);if(d.type==='magnet'){run.buffs.magnet=3;for(const g of run.gems){g.x=p.x;g.y=p.y;}}if(d.type==='bomb'){for(const e of run.enemies)damageEnemy(e,1000);if(run.boss)damageEnemy(run.boss,run.boss.maxHp*.12);}if(d.type==='hourglass')run.buffs.freeze=5;if(d.type==='fury')run.buffs.fury=10;if(d.type==='shield')run.buffs.shield=8;d.got=true;say(info.name+' collected');audio.play('powerup');}}run.drops=run.drops.filter(d=>!d.got);
 for(const f of floating)f.t+=dt;floating=floating.filter(f=>f.t<f.life);for(const q of particles){q.life-=dt;if(!q.slash&&!q.flash){q.x+=(q.vx||0)*dt;q.y+=(q.vy||0)*dt;}}particles=particles.filter(q=>q.life>0);run.shake=Math.max(0,run.shake-dt*28);if(Math.floor(run.elapsed*4)%4===0)updateHud();}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);if(!run){world.draw(ctx,0,0,vw,vh);return;}const p=run.player,cx=p.x,cy=p.y,shake=run.shake?rand(-run.shake,run.shake):0;ctx.save();ctx.translate(shake,shake);world.draw(ctx,cx,cy,vw,vh);const sx=x=>x-cx+vw/2,sy=y=>y-cy+vh/2;
 for(const g of run.gems)drawSprite(ctx,gemSpriteFor(g.value),sx(g.x),sy(g.y),.72);for(const d of run.drops){drawSprite(ctx,d.type==='heart'?'heart':d.type==='bomb'?'bomb':d.type==='hourglass'?'hourglass':d.type==='magnet'?'magnet':d.type==='fury'?'fury':d.type==='shield'?'crown':'heart',sx(d.x),sy(d.y),.85);}
 for(const z of run.zones){ctx.globalAlpha=.22;ctx.fillStyle=z.color;ctx.beginPath();ctx.arc(sx(z.x),sy(z.y),z.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=z.color;ctx.beginPath();ctx.arc(sx(z.x),sy(z.y),z.r,0,Math.PI*2);ctx.stroke();}
 for(const s of run.shots){ctx.fillStyle=s.color;ctx.shadowColor=s.color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(sx(s.x),sy(s.y),s.r,0,7);ctx.fill();ctx.shadowBlur=0;}
 for(const e of run.enemies){const key=e.id==='ghoul'?`ghoul_${Math.floor(e.anim/8)%3}`:e.id==='bat'?`bat_${Math.floor(e.anim/8)%2}`:e.id;drawSprite(ctx,key,sx(e.x),sy(e.y),e.r/7,e.x<p.x,e.slow?.55:1);if(e.maxHp>45){ctx.fillStyle='#160f20';ctx.fillRect(sx(e.x)-10,sy(e.y)-22,20,3);ctx.fillStyle='#e87588';ctx.fillRect(sx(e.x)-10,sy(e.y)-22,20*Math.max(0,e.hp/e.maxHp),3);}}
