 for(const f of floating){ctx.globalAlpha=1-f.t/f.life;ctx.fillStyle=f.color;ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(f.text,sx(f.x),sy(f.y)-f.t*20);}ctx.globalAlpha=1;ctx.restore();}
function loop(now){if(state==='playing'){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);}draw();if(state==='playing'||state==='menu'||state==='paused'||state==='levelup')raf=requestAnimationFrame(loop);}
