function bindSettings(){for(const [el,key]of [[ui.musicVol,'music'],[ui.sfxVol,'sfx']])el.addEventListener('input',()=>{settings[key]=Number(el.value);(key==='music'?ui.musicVolOut:ui.sfxVolOut).value=el.value;key==='music'?audio.setMusicVolume(settings.music):audio.setSfxVolume(settings.sfx);saveSettings();});for(const [el,key]of [[ui.shakeToggle,'shake'],[ui.dmgToggle,'damage'],[ui.qualitySelect,'quality'],[ui.joystickSelect,'joystick']])el.addEventListener('change',()=>{settings[key]=el.type==='checkbox'?el.checked:el.value;saveSettings();syncSettings();});}
