9: export class AudioEngine {
10:   constructor(settings = {}) {
11:     this.ctx = null;
12:     this.master = null;
13:     this.musicGain = null;
14:     this.sfxGain = null;
15:     this.noiseBuffer = null;
16:     this.musicVolume = (settings.music ?? 55) / 100;
17:     this.sfxVolume = (settings.sfx ?? 80) / 100;
18:     this.musicOn = false;
19:     this.intensity = 0;
20:     this.step = 0;
21:     this.nextTime = 0;
22:     this.timer = null;
23:     this.lastSfx = Object.create(null);
24:     this.duckAmount = 0;
25:     this.muted = false;
26:   }
27: 
28:   ensure() {
29:     if (this.ctx) {
30:       if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
31:       return true;
32:     }
33:     const AC = window.AudioContext || window.webkitAudioContext;
34:     if (!AC) return false;
35:     try {
36:       const ctx = new AC();
37:       this.ctx = ctx;
38:       const master = ctx.createGain();
39:       master.gain.value = 0.9;
40:       const comp = ctx.createDynamicsCompressor();
41:       comp.threshold.value = -14;
42:       comp.knee.value = 18;
43:       comp.ratio.value = 4;
44:       comp.attack.value = 0.003;
45:       comp.release.value = 0.2;
46:       master.connect(comp).connect(ctx.destination);
47:       this.master = master;
48: 
49:       const music = ctx.createGain();
50:       music.gain.value = 0;
51:       music.connect(master);
52:       this.musicGain = music;
53: 
54:       const sfx = ctx.createGain();
55:       sfx.gain.value = this.sfxVolume;
56:       sfx.connect(master);
57:       this.sfxGain = sfx;
58: 
59:       // 1s of noise for percussive effects
60:       const len = ctx.sampleRate;
61:       const buf = ctx.createBuffer(1, len, ctx.sampleRate);
62:       const data = buf.getChannelData(0);
63:       for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
64:       this.noiseBuffer = buf;
65: 
66:       if (ctx.state === 'suspended') ctx.resume().catch(() => {});
67:       return true;
68:     } catch {
69:       return false;
70:     }
71:   }
72: 
73:   setMusicVolume(v) {
74:     this.musicVolume = Math.max(0, Math.min(1, v / 100));
75:     if (this.musicGain && this.ctx) {
76:       const target = this.musicOn ? this.musicVolume * 0.5 * (1 - this.duckAmount) : 0;
77:       this.musicGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.12);
78:     }
79:   }
80: 
81:   setSfxVolume(v) {
82:     this.sfxVolume = Math.max(0, Math.min(1, v / 100));
83:     if (this.sfxGain) this.sfxGain.gain.setTargetAtTime(this.sfxVolume, this.ctx.currentTime, 0.08);
84:   }
85: 
86:   duck(on) {
87:     this.duckAmount = on ? 0.55 : 0;
88:     if (this.musicGain && this.ctx) {
89:       this.musicGain.gain.setTargetAtTime(this.musicOn ? this.musicVolume * 0.5 * (1 - this.duckAmount) : 0, this.ctx.currentTime, 0.15);
90:     }
91:   }
92: 
93:   startMusic() {
94:     if (!this.ensure()) return;
95:     if (this.musicOn) return;
96:     this.musicOn = true;
97:     this.step = 0;
98:     this.nextTime = this.ctx.currentTime + 0.1;
99:     this.musicGain.gain.setTargetAtTime(this.musicVolume * 0.5 * (1 - this.duckAmount), this.ctx.currentTime, 0.6);
100:     if (this.timer) clearInterval(this.timer);
101:     this.timer = setInterval(() => this.schedule(), 80);
102:     this.schedule();
103:   }
104: 
105:   stopMusic() {
106:     this.musicOn = false;
107:     if (this.timer) { clearInterval(this.timer); this.timer = null; }
108:     if (this.musicGain && this.ctx) this.musicGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.25);
109:   }
110: 
111:   setIntensity(v) { this.intensity = Math.max(0, Math.min(1, v)); }
112: 
113:   schedule() {
114:     if (!this.ctx || !this.musicOn) return;
115:     const ahead = 0.3;
116:     while (this.nextTime < this.ctx.currentTime + ahead) {
117:       this.playStep(this.step, this.nextTime);
118:       this.nextTime += 60 / 76 / 2; // eighth notes at 76 BPM
119:       this.step = (this.step + 1) % 128;
120:     }
121:   }
122: 
123:   playStep(step, t) {
124:     const ctx = this.ctx;
125:     const bar = Math.floor(step / 8) % 16;
126:     const inBar = step % 8;
127:     const inten = this.intensity;
128:     // D minor / Bb / Gm / A, two bars each
129:     const chords = [
130:       { root: ['D', 2], tones: [['D', 3], ['F', 3], ['A', 3], ['D', 4]] },
131:       { root: ['D', 2], tones: [['D', 3], ['F', 3], ['A', 3], ['D', 4]] },
132:       { root: ['A#', 1], tones: [['A#', 2], ['D', 3], ['F', 3], ['A#', 3]] },
133:       { root: ['A#', 1], tones: [['A#', 2], ['D', 3], ['F', 3], ['A#', 3]] },
134:       { root: ['G', 1], tones: [['G', 2], ['A#', 2], ['D', 3], ['G', 3]] },
135:       { root: ['G', 1], tones: [['G', 2], ['A#', 2], ['D', 3], ['G', 3]] },
136:       { root: ['A', 1], tones: [['A', 2], ['C#', 3], ['E', 3], ['A', 3]] },
137:       { root: ['A', 1], tones: [['A', 2], ['C#', 3], ['E', 3], ['A', 3]] },
138:       { root: ['D', 2], tones: [['D', 3], ['F', 3], ['A', 3], ['D', 4]] },
139:       { root: ['D', 2], tones: [['D', 3], ['F', 3], ['A', 3], ['D', 4]] },
140:       { root: ['F', 1], tones: [['F', 2], ['A', 2], ['C', 3], ['F', 3]] },
141:       { root: ['F', 1], tones: [['F', 2], ['A', 2], ['C', 3], ['F', 3]] },
142:       { root: ['C', 2], tones: [['C', 3], ['E', 3], ['G', 3], ['C', 4]] },
143:       { root: ['C', 2], tones: [['C', 3], ['E', 3], ['G', 3], ['C', 4]] },
144:       { root: ['A', 1], tones: [['A', 2], ['C#', 3], ['E', 3], ['A', 3]] },
145:       { root: ['A', 1], tones: [['A', 2], ['C#', 3], ['E', 3], ['A', 3]] },
146:     ];
147:     const chord = chords[bar];
148: 
149:     // Pads at the top of each bar
150:     if (inBar === 0) {
151:       for (let i = 0; i < chord.tones.length; i++) {
152:         const [n, o] = chord.tones[i];
153:         this.pad(freq(n, o), t, 3.4, 0.035 + inten * 0.012, i);
154:       }
155:     }
156:     // Bass pulse
157:     if (inBar === 0 || inBar === 3 || (inBar === 6 && inten > 0.35)) {
158:       this.bass(freq(chord.root[0], chord.root[1]), t, inBar === 0 ? 0.55 : 0.34, 0.15);
159:     }
160:     // Sparse arpeggio
161:     if (inBar % 2 === 0 || inten > 0.5) {
162:       const tone = chord.tones[(step + Math.floor(step / 8)) % chord.tones.length];
163:       this.pluck(freq(tone[0], tone[1] + 1), t, 0.12 + inten * 0.06);
164:     }
165:     // Percussion layers with intensity
166:     if (inten > 0.18 && inBar % 2 === 1) this.hat(t, 0.025 + inten * 0.02);
167:     if (inten > 0.42 && inBar === 0) this.kick(t, 0.2);
168:     if (inten > 0.62 && inBar === 4) this.kick(t, 0.13);
169:     // Ominous bell every 4 bars
170:     if (inten > 0.55 && step % 32 === 0) {
171:       const [n, o] = chord.tones[3];
172:       this.bell(freq(n, o + 1), t, 0.08);
173:     }
174:   }
175: 
176:   pad(f, t, dur, vol, idx) {
177:     const ctx = this.ctx;
178:     const o = ctx.createOscillator();
179:     const g = ctx.createGain();
180:     const flt = ctx.createBiquadFilter();
181:     o.type = idx % 2 ? 'sawtooth' : 'triangle';
182:     o.frequency.value = f * (idx % 2 ? 1.004 : 0.996);
183:     flt.type = 'lowpass';
184:     flt.frequency.value = 620 + idx * 80;
185:     flt.Q.value = 0.7;
186:     g.gain.setValueAtTime(0, t);
187:     g.gain.linearRampToValueAtTime(vol, t + 0.5);
188:     g.gain.linearRampToValueAtTime(vol * 0.75, t + dur * 0.7);
189:     g.gain.linearRampToValueAtTime(0, t + dur);
190:     o.connect(flt).connect(g).connect(this.musicGain);
191:     o.start(t); o.stop(t + dur + 0.05);
192:   }
193: 
194:   bass(f, t, dur, vol) {
195:     const ctx = this.ctx;
196:     const o = ctx.createOscillator();
197:     const g = ctx.createGain();
198:     o.type = 'triangle';
199:     o.frequency.setValueAtTime(f * 1.02, t);
200:     o.frequency.exponentialRampToValueAtTime(f, t + 0.08);
201:     g.gain.setValueAtTime(0, t);
202:     g.gain.linearRampToValueAtTime(vol, t + 0.03);
203:     g.gain.exponentialRampToValueAtTime(0.001, t + dur);
204:     o.connect(g).connect(this.musicGain);
205:     o.start(t); o.stop(t + dur + 0.02);
206:   }
207: 
208:   pluck(f, t, vol) {
209:     const ctx = this.ctx;
210:     const o = ctx.createOscillator();
211:     const o2 = ctx.createOscillator();
212:     const g = ctx.createGain();
213:     o.type = 'triangle'; o2.type = 'sine';
214:     o.frequency.value = f; o2.frequency.value = f * 2.01;
215:     g.gain.setValueAtTime(0, t);
216:     g.gain.linearRampToValueAtTime(vol, t + 0.01);
217:     g.gain.exponentialRampToValueAtTime(0.0008, t + 0.55);
218:     o.connect(g); o2.connect(g); g.connect(this.musicGain);
219:     o.start(t); o.stop(t + 0.6); o2.start(t); o2.stop(t + 0.6);
220:   }
221: 
222:   bell(f, t, vol) {
223:     const ctx = this.ctx;
224:     const o = ctx.createOscillator();
225:     const g = ctx.createGain();
226:     o.type = 'sine';
227:     o.frequency.value = f;
228:     g.gain.setValueAtTime(0, t);
229:     g.gain.linearRampToValueAtTime(vol, t + 0.02);
230:     g.gain.exponentialRampToValueAtTime(0.0005, t + 2.4);
231:     o.connect(g).connect(this.musicGain);
232:     o.start(t); o.stop(t + 2.5);
233:   }
234: 
235:   hat(t, vol) {
236:     const ctx = this.ctx;
237:     const src = ctx.createBufferSource();
238:     src.buffer = this.noiseBuffer;
239:     const flt = ctx.createBiquadFilter();
240:     flt.type = 'highpass'; flt.frequency.value = 7200;
241:     const g = ctx.createGain();
242:     g.gain.setValueAtTime(vol, t);
243:     g.gain.exponentialRampToValueAtTime(0.0005, t + 0.055);
244:     src.connect(flt).connect(g).connect(this.musicGain);
245:     src.start(t); src.stop(t + 0.06);
246:   }
247: 
248:   kick(t, vol) {
249:     const ctx = this.ctx;
250:     const o = ctx.createOscillator();
251:     const g = ctx.createGain();
252:     o.type = 'sine';
253:     o.frequency.setValueAtTime(110, t);
254:     o.frequency.exponentialRampToValueAtTime(38, t + 0.13);
255:     g.gain.setValueAtTime(vol, t);
256:     g.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
257:     o.connect(g).connect(this.musicGain);
258:     o.start(t); o.stop(t + 0.22);
259:   }
260: 
261:   /* ---------------- SFX ---------------- */
262:   sfx(name, opts = {}) {
263:     if (!this.ctx || this.ctx.state !== 'running' || this.sfxVolume <= 0) return;
264:     const now = this.ctx.currentTime;
265:     const cooldown = opts.cooldown ?? SFX_COOLDOWN[name] ?? 0.03;
266:     const last = this.lastSfx[name] || 0;
267:     if (now - last < cooldown) return;
268:     this.lastSfx[name] = now;
269:     const vol = (opts.volume ?? 1) * (SFX_VOLUME[name] ?? 0.5);
270:     try { this['_' + name]?.(now, vol, opts); } catch { /* ignore audio glitches */ }
271:   }
272: 
273:   _noise(t, dur, vol, type, f0, f1, q = 1) {
274:     const ctx = this.ctx;
275:     const src = ctx.createBufferSource();
276:     src.buffer = this.noiseBuffer;
277:     const flt = ctx.createBiquadFilter();
278:     flt.type = type; flt.Q.value = q;
279:     flt.frequency.setValueAtTime(f0, t);
280:     flt.frequency.exponentialRampToValueAtTime(Math.max(40, f1), t + dur);
281:     const g = ctx.createGain();
282:     g.gain.setValueAtTime(vol, t);
283:     g.gain.exponentialRampToValueAtTime(0.0006, t + dur);
284:     src.connect(flt).connect(g).connect(this.sfxGain);
285:     src.start(t); src.stop(t + dur + 0.02);
286:   }
287: 
288:   _tone(t, type, f0, f1, dur, vol, detune = 0) {
289:     const ctx = this.ctx;
290:     const o = ctx.createOscillator();
291:     const g = ctx.createGain();
292:     o.type = type;
293:     o.detune.value = detune;
294:     o.frequency.setValueAtTime(f0, t);
295:     o.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
296:     g.gain.setValueAtTime(0, t);
297:     g.gain.linearRampToValueAtTime(vol, t + Math.min(0.012, dur * 0.2));
298:     g.gain.exponentialRampToValueAtTime(0.0006, t + dur);
299:     o.connect(g).connect(this.sfxGain);
300:     o.start(t); o.stop(t + dur + 0.02);
301:   }
302: 
303:   _hit(t, vol, o) { this._noise(t, 0.07, vol * 0.7, 'bandpass', o.crit ? 3200 : 1600, 500, 1.2); this._tone(t, 'square', o.crit ? 520 : 300, 110, 0.06, vol * 0.28); }
