cat > /tmp/opencode/validate-gravewake.mjs <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const failures = [];
async function testDesktop() {
  const page = await browser.newPage({ viewport: { width: 960, height: 600 } });
  page.on('pageerror', e => failures.push(`desktop: ${e.message}`));
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.locator('#startBtn').click({ timeout: 10000 });
  await page.waitForFunction(() => document.querySelector('#hud').classList.contains('') || !document.querySelector('#hud').classList.contains('hidden'));
  await page.keyboard.down('d'); await page.waitForTimeout(650); await page.keyboard.up('d');
  await page.keyboard.press('Escape');
  await page.waitForFunction(() => !document.querySelector('#pause').classList.contains('hidden'));
  const pausedTime = await page.locator('#timer').innerText();
  await page.waitForTimeout(1200);
  const stillPausedTime = await page.locator('#timer').innerText();
  if (pausedTime !== stillPausedTime) failures.push(`desktop: timer moved while paused (${pausedTime} to ${stillPausedTime})`);
  await page.locator('#resumeBtn').click();
  await page.waitForFunction(() => document.querySelector('#pause').classList.contains('hidden'));
  await page.waitForTimeout(1100);
  const resumedTime = await page.locator('#timer').innerText();
  if (resumedTime === pausedTime) failures.push('desktop: timer did not resume');
  await page.screenshot({ path: '/tmp/opencode/gravewake-capture/desktop-check.jpg', type: 'jpeg', quality: 62 });
  console.log(`desktop: start, keyboard movement, pause/resume OK (timer ${pausedTime} -> ${resumedTime})`);
  await page.close();
}
async function testMobile() {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  page.on('pageerror', e => failures.push(`mobile: ${e.message}`));
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.locator('#startBtn').click({ timeout: 10000 });
  await page.waitForTimeout(500);
  const canvas = page.locator('#game');
  const box = await canvas.boundingBox();
  await page.mouse.move(box.x + 95, box.y + 620);
  await page.mouse.down();
  await page.mouse.move(box.x + 155, box.y + 620, { steps: 4 });
  await page.waitForTimeout(600);
  await page.mouse.up();
  if (await page.locator('#hud').evaluate(el => el.classList.contains('hidden'))) failures.push('mobile: HUD not visible after start');
  await page.screenshot({ path: '/tmp/opencode/gravewake-capture/mobile-check.jpg', type: 'jpeg', quality: 62 });
  console.log('mobile: start and touch joystick interaction OK');
  await page.close();
}
try { await testDesktop(); await testMobile(); }
finally { await browser.close(); }
if (failures.length) { console.error(failures.join('\n')); process.exitCode = 1; }
EOF
node /tmp/opencode/validate-gravewake.mjs

